const rawItemId = {{workflowparams:item_id}};

// This workflow is called with a scalar id; tolerate an array form too.
let requested = [];
if (Array.isArray(rawItemId)) requested = rawItemId;
else if (rawItemId != null && rawItemId !== "") requested = [rawItemId];

// Digits only: these ids are interpolated into Get Item's SQL.
const itemIDs = [...new Set(requested.map((v) => String(v == null ? "" : v).trim()))].filter(
  (id) => /^[0-9]+$/.test(id)
);

return { itemIdCsv: itemIDs.join(',') };

const rows = {{node:sql_node_ItemBinds.data}} || [];
const customerId = {{workflowparams:customer_id}};

// sql-node rows sit at .data, and a single row comes back bare rather than in an array.
const items = Array.isArray(rows) ? rows : (rows ? [rows] : []);
const row0 = items.length > 0 ? items[0] : null;
if (!row0) return { descriptions: [] };

// Get Item returns table_cust_item_bind as a JSON_ARRAYAGG string.
const parseBinds = (v) => {
  if (Array.isArray(v)) return v;
  if (!v) return [];
  try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
};
const item = { ...row0, table_cust_item_bind: parseBinds(row0.cust_item_bind_json) };

// table_cust_item_bind is a subform array stored on the Item record itself --
// it has no collection of its own, so this single fetch is all the data access
// needed. Bind rows store the Customer's primary id; compare as trimmed strings.
const wanted = customerId == null ? "" : String(customerId).trim();
const binds = Array.isArray(item.table_cust_item_bind) ? item.table_cust_item_bind : [];

const descriptions = [];
for (const row of binds) {
  if (!row) continue;
  const rowCust = row.customer_id == null ? "" : String(row.customer_id).trim();
  if (!wanted || rowCust !== wanted) continue;
  const d = row.item_desc == null ? "" : String(row.item_desc).trim();
  // One customer may have several rows; skip blanks and duplicates.
  if (d && descriptions.indexOf(d) === -1) descriptions.push(d);
}

// No customer-specific description -> fall back to the item's own description.
if (descriptions.length === 0) {
  const fallback = item.material_desc == null ? "" : String(item.material_desc).trim();
  if (fallback) descriptions.push(fallback);
}

return { descriptions };
